import pytest
from candidate import sort_third


class TestSortThird:
    def test_seven_elements_normal_case(self):
        assert sort_third([5, 6, 3, 4, 8, 9, 2]) == [2, 6, 3, 4, 8, 9, 5]

    def test_three_elements_single_third_index(self):
        assert sort_third([1, 2, 3]) == [1, 2, 3]

    def test_empty_list_returns_empty_list(self):
        assert sort_third([]) == []

    def test_single_element_list(self):
        assert sort_third([7]) == [7]

    def test_two_elements_only_index_zero_divisible(self):
        assert sort_third([2, 1]) == [2, 1]

    def test_six_elements_two_third_indices(self):
        assert sort_third([6, 5, 4, 3, 2, 1]) == [3, 5, 4, 6, 2, 1]

    def test_nine_elements_three_third_indices(self):
        assert sort_third([9, 8, 7, 6, 5, 4, 3, 2, 1]) == [3, 8, 7, 6, 5, 4, 9, 2, 1]

    def test_twelve_elements_four_third_indices(self):
        assert sort_third([12, 1, 1, 11, 1, 1, 10, 1, 1, 9, 1, 1]) == [9, 1, 1, 10, 1, 1, 11, 1, 1, 12, 1, 1]

    def test_already_sorted_at_third_indices(self):
        assert sort_third([1, 5, 5, 2, 5, 5, 3, 5, 5]) == [1, 5, 5, 2, 5, 5, 3, 5, 5]

    def test_reverse_sorted_at_third_indices(self):
        assert sort_third([9, 2, 2, 7, 2, 2, 5, 2, 2]) == [5, 2, 2, 7, 2, 2, 9, 2, 2]

    def test_negative_numbers_at_third_indices(self):
        assert sort_third([-3, 1, 1, -1, 1, 1, -2, 1, 1]) == [-3, 1, 1, -2, 1, 1, -1, 1, 1]

    def test_mixed_positive_negative_at_third_indices(self):
        assert sort_third([10, 0, 0, -5, 0, 0, 3, 0, 0]) == [-5, 0, 0, 3, 0, 0, 10, 0, 0]

    def test_all_same_elements(self):
        assert sort_third([4, 4, 4, 4, 4, 4, 4, 4, 4]) == [4, 4, 4, 4, 4, 4, 4, 4, 4]

    def test_zero_values(self):
        assert sort_third([0, 1, 1, 0, 1, 1, 0, 1, 1]) == [0, 1, 1, 0, 1, 1, 0, 1, 1]

    def test_float_values(self):
        assert sort_third([3.5, 1, 1, 2.5, 1, 1, 1.5, 1, 1]) == [1.5, 1, 1, 2.5, 1, 1, 3.5, 1, 1]

    def test_mixed_int_and_float_at_third_indices(self):
        assert sort_third([2.0, 1, 1, 3, 1, 1, 1.5, 1, 1]) == [1.5, 1, 1, 2.0, 1, 1, 3, 1, 1]

    def test_tuple_input_converts_to_list(self):
        result = sort_third((5, 6, 3, 4, 8, 9, 2))
        assert result == [2, 6, 3, 4, 8, 9, 5]
        assert isinstance(result, list)

    def test_string_input_produces_list(self):
        result = sort_third("hello")
        assert result == ['h', 'e', 'l', 'l', 'o']
        assert isinstance(result, list)

    def test_does_not_modify_original_list(self):
        original = [5, 6, 3, 4, 8, 9, 2]
        result = sort_third(original)
        assert original == [5, 6, 3, 4, 8, 9, 2]
        assert result == [2, 6, 3, 4, 8, 9, 5]

    def test_tuple_input_not_modified(self):
        t = (5, 6, 3, 4, 8, 9, 2)
        sort_third(t)
        assert t == (5, 6, 3, 4, 8, 9, 2
